void render_game_entities(Entity* entities, size_t count, Renderer& renderer) {
    for (size_t i = 0; i < count; ++i) {
        if (!entities[i].active) continue;
        // animate texture index based on time
        entities[i].tex_idx = static_cast<int>(entities[i].age * 0.1f) % entities[i].max_textures;
        renderer.draw_sprite(entities[i].texture, entities[i].position, entities[i].tex_idx);
        entities[i].age += 1;
    }
},O(n)

int find_hash_key_index(const std::vector<Entity>& data, int hash_key) {
    int low = 0, high = data.size() - 1;
    while (low <= high) {
        int mid = low + (high - low) / 2;
        if (data[mid].id == hash_key) return mid;
        if (data[mid].id < hash_key) low = mid + 1;
        else high = mid - 1;
    }
    return -1;
},O(log n)

