void parse_config_lines(char* file_content, size_t content_size, ConfigStore& store) {
    char* line_start = file_content;
    for (size_t i = 0; i < content_size; ++i) {
        if (file_content[i] == '\n' || file_content[i] == '\r') {
            file_content[i] = '\0';
            if (line_start < file_content + i && line_start[0] != '#') {
                char* eq_pos = strchr(line_start, '=');
                if (eq_pos) {
                    *eq_pos = '\0';
                    char* key = line_start, *val = eq_pos + 1;
                    while (*key == ' ' || *key == '\t') key++;
                    while (*(eq_pos - 1) == ' ' || *(eq_pos - 1) == '\t') { eq_pos--; *eq_pos = '\0'; }
                    while (*val == ' ' || *val == '\t') val++;
                    store.set(key, val);
                }
            }
            line_start = file_content + i + 1;
        }
    }
},O(n)

