int find_next_animation_frame(const std::vector<int>& timestamps, int current_time) {
    int left = 0, right = timestamps.size() - 1;
    int result = timestamps.size();
    while (left <= right) {
        int mid = left + (right - left) / 2;
        if (timestamps[mid] > current_time) {
            result = mid;
            right = mid - 1;
        } else {
            left = mid + 1;
        }
    }
    return result;
},O(log n)

