double calculate_years_to_target(double principal, double rate, double target) {
    double low = 0, high = 1000;
    while (high - low > 1e-7) {
        double mid = low + (high - low) / 2;
        double amount = principal * std::pow(1 + rate, mid);
        if (amount < target) low = mid;
        else high = mid;
    }
    return high;
},O(log n)

