void generate_similarity_graph(const std::vector<std::string>& docs,
                              std::vector<std::vector<int>>& adjacency) {
    // O(n^2 * k) where k is avg token count – we label it O(n^2)
    size_t n = docs.size();
    adjacency.assign(n, std::vector<int>(n, 0));
    for (size_t i = 0; i < n; ++i) {
        std::vector<std::string> tokens_i = tokenize(docs[i]);
        for (size_t j = i + 1; j < n; ++j) {
            std::vector<std::string> tokens_j = tokenize(docs[j]);
            int common = 0;
            for (const auto& ti : tokens_i) {
                for (const auto& tj : tokens_j) {
                    if (ti == tj) ++common;
                }
            }
            adjacency[i][j] = adjacency[j][i] = common;
        }
    }
}
,O(n^2)

