void evaluate_ast_dependencies(ASTNode* root, const std::unordered_map<ASTNode*, std::vector<ASTNode*>>& dependencies) {
    std::stack<ASTNode*> s;
    std::unordered_set<ASTNode*> processed;
    s.push(root);
    while (!s.empty()) {
        ASTNode* node = s.top();
        bool all_processed = true;
        for (ASTNode* dep : dependencies.at(node)) {
            if (processed.find(dep) == processed.end()) {
                s.push(dep);
                all_processed = false;
                break;
            }
        }
        if (all_processed) {
            node->evaluate();
            processed.insert(node);
            s.pop();
        }
    }
},O(V + E)

int count_synonym_clusters(const std::vector<std::string>& words) {
    int clusters = 0;
    for (const auto& word : words) {
        for (const auto& other : words) {
            if (word != other && word.find(other) != std::string::npos) {
                ++clusters;
            }
        }
    }
    return clusters / 2;
},O(n^2)

