void resolve_game_collisions(std::vector<GameObject>& objects, const std::unordered_map<int, std::vector<int>>& adjacency) {
    std::queue<int> q;
    std::unordered_set<int> visited;
    for (int i = 0; i < objects.size(); ++i) {
        if (objects[i].isColliding && visited.find(i) == visited.end()) {
            q.push(i);
            visited.insert(i);
            while (!q.empty()) {
                int current = q.front(); q.pop();
                for (int neighbor : adjacency.at(current)) {
                    if (visited.find(neighbor) == visited.end()) {
                        objects[neighbor].flagForResolution = true;
                        q.push(neighbor);
                        visited.insert(neighbor);
                    }
                }
            }
        }
    }
},O(V + E)

