void resolve_shader_dependencies(std::vector<Shader>& shaders, const std::unordered_map<int, std::vector<int>>& dependencies) {
    std::unordered_set<int> resolved;
    std::queue<int> q;
    for (int i = 0; i < shaders.size(); ++i) {
        if (dependencies.find(i) == dependencies.end() || dependencies.at(i).empty()) {
            q.push(i);
            resolved.insert(i);
        }
    }
    while (!q.empty()) {
        int current = q.front(); q.pop();
        shaders[current].compile();
        for (int i = 0; i < shaders.size(); ++i) {
            auto& deps = dependencies.at(i);
            if (std::find(deps.begin(), deps.end(), current) != deps.end() && resolved.find(i) == resolved.end()) {
                deps.erase(std::remove(deps.begin(), deps.end(), current), deps.end());
                if (deps.empty()) {
                    q.push(i);
                    resolved.insert(i);
                }
            }
        }
    }
},O(V + E)

