void pathfind_astar(Node& start, Node& goal) {
    std::vector<Node*> open_list;
    std::unordered_set<Node*> closed_list;
    start.g_cost = 0;
    start.h_cost = heuristic(start, goal);
    start.f_cost = start.g_cost + start.h_cost;
    open_list.push_back(&start);
    while (!open_list.empty()) {
        Node* current = open_list[0];
        int current_idx = 0;
        for (size_t i = 1; i < open_list.size(); i++) {
            if (open_list[i]->f_cost < current->f_cost) {
                current = open_list[i];
                current_idx = i;
            }
        }
        open_list.erase(open_list.begin() + current_idx);
        closed_list.insert(current);
        if (current == &goal) {
            reconstruct_path(current);
            return;
        }
        for (Node* neighbor : current->neighbors) {
            if (closed_list.find(neighbor) != closed_list.end()) continue;
            float tentative_g = current->g_cost + neighbor->cost;
            bool in_open = false;
            for (auto node : open_list) {
                if (node == neighbor) {
                    in_open = true;
                    if (tentative_g < neighbor->g_cost) {
                        neighbor->parent = current;
                        neighbor->g_cost = tentative_g;
                        neighbor->f_cost = neighbor->g_cost + neighbor->h_cost;
                    }
                    break;
                }
            }
            if (!in_open) {
                neighbor->parent = current;
                neighbor->g_cost = tentative_g;
                neighbor->f_cost = neighbor->g_cost + neighbor->h_cost;
                open_list.push_back(neighbor);
            }
        }
    }
    path_found = false;
},O(n)

