std::vector<std::pair<std::string, std::string>> find_similar_words(const std::vector<std::string>& dictionary) {
    std::vector<std::pair<std::string, std::string>> matches;
    for (size_t i = 0; i < dictionary.size(); ++i) {
        for (size_t j = i + 1; j < dictionary.size(); ++j) {
            int edits = levenshtein_distance(dictionary[i], dictionary[j]);
            if (edits <= 2) {
                matches.emplace_back(dictionary[i], dictionary[j]);
            }
        }
    }
    return matches;
},O(n^2)

