float sensor_calibrate_reading(uint16_t raw_adc, const std::vector<uint16_t>& sorted_adc_values, const std::vector<float>& calibrated_values) {
    size_t n = sorted_adc_values.size();
    if (n == 0) return 0.0f;
    if (raw_adc <= sorted_adc_values[0]) return calibrated_values[0];
    if (raw_adc >= sorted_adc_values[n-1]) return calibrated_values[n-1];

    int low = 0, high = n - 1;
    int idx = 0;
    while (low <= high) {
        int mid = low + (high - low) / 2;
        if (sorted_adc_values[mid] == raw_adc) {
            return calibrated_values[mid];
        } else if (sorted_adc_values[mid] < raw_adc) {
            low = mid + 1;
        } else {
            high = mid - 1;
        }
    }
    idx = high;
    float t = (raw_adc - sorted_adc_values[idx]) / (float)(sorted_adc_values[idx+1] - sorted_adc_values[idx]);
    return calibrated_values[idx] + t * (calibrated_values[idx+1] - calibrated_values[idx]);
},O(log n)

