        for (size_t j = i + 1; j < transactions.size(); ++j) {
            if (transactions[i].id == transactions[j].id ||
                (transactions[i].amount == transactions[j].amount &&
                 transactions[i].merchant_id == transactions[j].merchant_id &&
                 abs(transactions[i].timestamp - transactions[j].timestamp) < 300)) {
                trigger_fraud_alert(transactions[i].id, transactions[j].id);
