    std::string current;
    for (char c : line) {
        if (c == delimiter || c == '\n') {
            fields.push_back(current);
            current.clear();
        } else if (c != '\r') {
            current += c;
        }
    }
    if (!current.empty()) fields.push_back(current);
    return fields;
},O(n)

