struct Waypoint {
    double x, y;
};
std::vector<Waypoint> optimize_route(const std::vector<Waypoint>& waypoints) {
    std::vector<std::pair<double, Waypoint>> distances;
    Waypoint start = waypoints[0];
    for (const auto& wp : waypoints) {
        if (&wp == &start) continue;
        double dist = std::sqrt(std::pow(start.x - wp.x, 2) + std::pow(start.y - wp.y, 2));
        distances.emplace_back(dist, wp);
    }
    std::sort(distances.begin(), distances.end(), 
        [](const auto& a, const auto& b) { return a.first < b.first; });
    std::vector<Waypoint> sorted;
    sorted.push_back(start);
    for (const auto& p : distances) sorted.push_back(p.second);
    return sorted;
},O(n log n)

