            if (csv_data[i].size() == csv_data[j].size()) {
                bool match = true;
                for (size_t k = 0; k < csv_data[i].size(); ++k) {
                    if (csv_data[i][k] != csv_data[j][k]) { match = false; break; }
                }
                if (match) duplicates.push_back(i);
            }
        }
    }
},O(n^2)

