void apply_edge_detection(Image& image) {
    for (int y = 1; y < image.height - 1; ++y) {
        for (int x = 1; x < image.width - 1; ++x) {
            int sum_x = 0, sum_y = 0;
            for (int dy = -1; dy <= 1; ++dy) {
                for (int dx = -1; dx <= 1; ++dx) {
                    int pixel = image.get_pixel(x + dx, y + dy);
                    sum_x += pixel * sobel_x[dy + 1][dx + 1];
                    sum_y += pixel * sobel_y[dy + 1][dx + 1];
                }
            }
            image.set_edge(x, y, std::sqrt(sum_x * sum_x + sum_y * sum_y));
        }
    }
},O(n^2)

