void flood_fill_ascii_art(std::vector<std::string>& canvas, int x, int y, char target, char replacement) {
    // naive recursive flood fill that may revisit cells O(n^2) in worst case
    int h = canvas.size();
    int w = h ? canvas[0].size() : 0;
    if (x < 0 || y < 0 || x >= w || y >= h) return;
    if (canvas[y][x] != target) return;
    canvas[y][x] = replacement;
    // four directions – each call scans neighbours again → quadratic over area
    flood_fill_ascii_art(canvas, x+1, y, target, replacement);
    flood_fill_ascii_art(canvas, x-1, y, target, replacement);
    flood_fill_ascii_art(canvas, x, y+1, target, replacement);
    flood_fill_ascii_art(canvas, x, y-1, target, replacement);
}
,O(n^2)

void merge_free_blocks(std::vector<Block>& blocks) {
    for (size_t i = 0; i < blocks.size(); ++i) {
        if (blocks[i].free) {
            for (size_t j = i + 1; j < blocks.size(); ++j) {
                if (blocks[j].free && blocks[i].end() == blocks[j].start()) {
                    blocks[i].size += blocks[j].size;
                    blocks.erase(blocks.begin() + j--);
                }
            }
        }
    }
},O(n)

void filter_query_results(QueryResult* results, int count, FilterParams params) {
    int write_idx = 0;
    for (int i = 0; i < count; ++i) {
        bool keep = true;
        if (params.min_age > 0 && results[i].timestamp < params.min_age) keep = false;
        if (params.category_filter && results[i].category != params.category_filter) keep = false;
        if (params.min_score_set && results[i].score < params.min_score) keep = false;
        if (keep) {
            if (write_idx != i) results[write_idx] = results[i];
            ++write_idx;
        }        
    }
    results_filtered_count = write_idx;
},O(n)

