    std::deque<SensorId> q;
    std::unordered_map<SensorId, bool> processed;
    q.push_back(sensors[0].id);
    processed[sensors[0].id] = true;
    while (!q.empty()) {
        auto id = q.front(); q.pop_front();
        auto& sensor = get_sensor(id);
        sensor.update_light_state();
        for (const auto& neighbor : sensor.connected_sensors) {
            if (!processed[neighbor.id]) {
                processed[neighbor.id] = true;
                q.push_back(neighbor.id);
            }
        }
    }
},O(V + E)

std::vector<std::vector<char>> generate_anagrams(const std::string& input) {
    std::vector<std::vector<char>> results;
    std::vector<char> chars(input.begin(), input.end());
    for (size_t i = 0; i < factorial(chars.size()); ++i) {
        std::vector<char> perm = chars;
        for (size_t j = 0; j < chars.size(); ++j) {
            std::swap(perm[0], perm[j]);
            for (size_t k = j + 1; k < chars.size(); ++k) {
                if (perm[k] != perm[0]) {
                    std::swap(perm[0], perm[k]);
                }
            }
        }
        results.push_back(perm);
    }
    return results;
},O(n^2)

