void render_game_frame(std::vector<Renderable*>& objects, Camera* camera) {
    struct CompareDepth {
        Camera* cam;
        bool operator()(Renderable* a, Renderable* b) {
            float dist_a = glm::distance(cam->position, a->get_position());
            float dist_b = glm::distance(cam->position, b->get_position());
            return dist_a > dist_b; // Closer objects first
        }
    };
    std::sort(objects.begin(), objects.end(), CompareDepth{camera});
    for (auto obj : objects) {
        if (obj->is_visible()) {
            obj->render();
        }
    }
    // Clean up any objects that might have been marked for deletion during rendering
    objects.erase(std::remove_if(objects.begin(), objects.end(), [](Renderable* o) {
        return o->marked_for_deletion;
    }), objects.end());
},O(n log n)

void render_particles() {
    static float particle_buffer[1024][3];
    int count = 0;
    for (const auto& emitter : particle_emitters) {
        if (emitter.active) {
            for (int i = 0; i < emitter.particle_count; i++) {
                particle_buffer[count][0] = emitter.particles[i].position.x;
                particle_buffer[count][1] = emitter.particles[i].position.y;
                particle_buffer[count][2] = emitter.particles[i].position.z;
                count++;
                if (count >= 1024) break;
            }
        }
    }
    glBufferSubData(GL_ARRAY_BUFFER, 0, count * sizeof(float) * 3, particle_buffer);
    glDrawArrays(GL_POINTS, 0, count);
},O(n)

