    for (size_t i = 0; i < events.size(); ++i) {
        for (size_t j = 0; j < events.size(); ++j) {
            if (i == j) continue;
            DateTime start = max(events[i].first, events[j].first);
            DateTime end = min(events[i].second, events[j].second);
            if (start < end) {
                cout << "Overlapping events: " << i << " and " << j << endl;
            }
        }
    }
},O(n^2)

