void process_audio_graph(AudioNode& root) {
    std::stack<AudioNode*> s;
    std::unordered_map<AudioNode*, bool> processed;
    s.push(&root);
    while (!s.empty()) {
        auto node = s.top(); s.pop();
        if (!processed[node]) {
            processed[node] = true;
            node->pull_input_buffers();
            for (auto& child : node->outputs) {
                s.push(child.target_node);
