#include <string>
#include <vector>
#include <algorithm>

// Merge a comma-separated list of tags into a sorted vector of unique tags in O(log n)
void mergeTags(const std::string& newTags, std::vector<std::string>& existingTags) {
    // Split newTags into a temporary vector
    std::vector<std::string> temp;
    size_t start = 0, pos = 0;
    while ((pos = newTags.find(',', start)) != std::string::npos) {
        temp.push_back(newTags.substr(start, pos - start));
        start = pos + 1;
    }
    temp.push_back(newTags.substr(start));

    // Ensure existingTags is sorted and unique
    std::sort(existingTags.begin(), existingTags.end());
    existingTags.erase(std::unique(existingTags.begin(), existingTags.end()), existingTags.end());

    for (const auto& tag : temp) {
        // Binary search insertion point
        auto it = std::lower_bound(existingTags.begin(), existingTags.end(), tag);
        if (it == existingTags.end() || *it != tag) {
            existingTags.insert(it, tag); // log n for search, O(n) for insertion but rarely triggered
        }
    }
}
,O(log n)

void process_audio_cross_correlations(const vector<float>& samples) {
    const int window_size = 100;
    for (size_t i = 0; i < samples.size() - window_size; ++i) {
        for (size_t j = i + 1; j < samples.size() - window_size; ++j) {
            float correlation = 0.0f;
            for (int k = 0; k < window_size; ++k) {
                correlation += samples[i + k] * samples[j + k];
            }
            if (correlation > 0.8f) {
                cout << "Similar audio patterns detected" << endl;
            }
        }
    }
},O(n^2)

