    std::stack<const FileNode*> s;
    std::unordered_map<const FileNode*, bool> visited;
    s.push(&root);
    while (!s.empty()) {
        auto node = s.top(); s.pop();
        if (!visited[node]) {
            visited[node] = true;
            if (node->is_temp()) node->delete_async();
            for (const auto& child : node->children) {
