    for (size_t i = 0; i < filenames.size(); ++i) {
        uintmax_t size_i = std::filesystem::file_size(filenames[i]);
        for (size_t j = i + 1; j < filenames.size(); ++j) {
            if (size_i == std::filesystem::file_size(filenames[j])) {
                std::string hash_i = compute_md5(filenames[i]);
                std::string hash_j = compute_md5(filenames[j]);
                if (hash_i == hash_j) {
                    logger->warn("Duplicate file detected: {} and {}", filenames[i], filenames[j]);
                    if (!config.silent_mode) {
                        play_alert_sound();
                    }
                }
            }
        }
    }
},O(n^2)

