void validate_user_input(const std::map<std::string, std::string>& input) {
    static const std::regex email_regex(R"(\w+@\w+\.\w+)");
    static const std::regex phone_regex(R"(\d{3}-\d{3}-\d{4})");
    for (const auto& field : input) {
        if (field.first == "email" && !std::regex_match(field.second, email_regex)) {
            validation_errors.push_back("Invalid email format");
        }
        if (field.first == "phone" && !std::regex_match(field.second, phone_regex)) {
            validation_errors.push_back("Invalid phone format");
        }
        if (field.first == "age" && (std::stoi(field.second) < 18 || std::stoi(field.second) > 120)) {
            validation_errors.push_back("Age must be between 18 and 120");
        }
    }
},O(n)

