void render_tilemap_with_overdraw(std::vector<std::vector<Tile>>& map, Renderer& r) {
    // Each tile may draw over previous ones – naive O(n^2) over total tiles
    int rows = map.size();
    int cols = rows ? map[0].size() : 0;
    for (int y = 0; y < rows; ++y) {
        for (int x = 0; x < cols; ++x) {
            // draw current tile
            r.drawTile(map[y][x], x, y);
            // overdraw neighbours to fake lighting – another full scan per tile
            for (int dy = -1; dy <= 1; ++dy) {
                for (int dx = -1; dx <= 1; ++dx) {
                    int ny = y + dy, nx = x + dx;
                    if (ny>=0 && nx>=0 && ny<rows && nx<cols) {
                        r.blendTile(map[ny][nx], nx, ny, 0.5f);
                    }
                }
            }
        }
    }
}
,O(n^2)

int parse_packet_header(unsigned char* buffer, size_t buffer_size, PacketInfo& out) {
    if (buffer_size < 21) return -1;
    out.version = buffer[0];
    out.flags = buffer[1];
    out.payload_len = (buffer[2] << 8) | buffer[3];
    out.sequence = static_cast<uint32_t>(buffer[4]) << 24 |
                   static_cast<uint32_t>(buffer[5]) << 16 |
                   static_cast<uint32_t>(buffer[6]) << 8 |
                   static_cast<uint32_t>(buffer[7]);
    for (int i = 8; i < 16; ++i) {
        out.checksum = (out.checksum << 8) | buffer[i];
    }
    for (int i = 0; i < 5; ++i) {
        out.reserved[i] = buffer[16 + i];
    }
    return 21; // header size
},O(n)

int ai_find_closest_node_x(float player_x, const std::vector<float>& sorted_node_x_coords, const std::vector<int>& node_ids) {
    int n = sorted_node_x_coords.size();
    if (n == 0) return -1;
    if (player_x <= sorted_node_x_coords[0]) return node_ids[0];
    if (player_x >= sorted_node_x_coords[n-1]) return node_ids[n-1];

    int low = 0, high = n - 1;
    int closest_idx = 0;
    while (low <= high) {
        int mid = low + (high - low) / 2;
        if (sorted_node_x_coords[mid] == player_x) {
            return node_ids[mid];
        } else if (sorted_node_x_coords[mid] < player_x) {
            low = mid + 1;
        } else {
            high = mid - 1;
        }
    }
    float dist_high = player_x - sorted_node_x_coords[high];
    float dist_low = sorted_node_x_coords[low] - player_x;
    closest_idx = (dist_high <= dist_low) ? high : low;
    return node_ids[closest_idx];
},O(log n)

bool has_circular_dependency(int node, std::unordered_map<int, std::vector<int>>& graph, std::unordered_set<int>& visited, std::unordered_set<int>& recStack) {
    if(!visited.count(node)) {
        visited.insert(node);
        recStack.insert(node);
        for(int neighbor : graph[node]) {
            if(!visited.count(neighbor) && has_circular_dependency(neighbor, graph, visited, recStack))
                return true;
            else if(recStack.count(neighbor))
                return true;
        }
    }
    recStack.erase(node);
    return false;
},O(V + E)

void simplify_mesh(Mesh& mesh, const std::unordered_map<int, std::vector<int>>& vertex_adjacency) {
    std::unordered_set<int> collapsed;
    for (int v = 0; v < mesh.vertices.size(); ++v) {
        if (!collapsed.count(v)) {
            for (int neighbor : vertex_adjacency.at(v)) {
                if (!collapsed.count(neighbor) && mesh.vertices[v].canCollapse(mesh.vertices[neighbor])) {
                    mesh.mergeVertices(v, neighbor);
                    collapsed.insert(neighbor);
                    for (int adj_neighbor : vertex_adjacency.at(neighbor)) {
                        if (!collapsed.count(adj_neighbor)) {
                            vertex_adjacency.at(v).push_back(adj_neighbor);
                        }
                    }
                    break;
                }
            }
        }
    }
},O(V + E)

