    int low = 0, high = sorted_primes.size() - 1;
    uint32_t result = 0;
    while (low <= high) {
        int mid = low + (high - low) / 2;
        if (sorted_primes[mid] <= n) {
            result = sorted_primes[mid];
            low = mid + 1;
        } else {
            high = mid - 1;
        }
    }
    return result;
},O(log n)

float adjust_volume_db(float current_db, float target_db) {
    float low = current_db, high = target_db;
    while (high - low > 0.01f) {
        float mid = low + (high - low) / 2;
        float adjusted = std::max(-60.0f, mid);
        if (adjusted < target_db) low = mid;
        else high = mid;
    }
    return high;
