void compress_image_data(std::vector<uint8_t>& raw_data) {
    std::vector<uint8_t> compressed;
    uint8_t current = raw_data[0];
    uint8_t count = 1;
    for (size_t i = 1; i < raw_data.size(); i++) {
        if (raw_data[i] == current && count < 255) {
            count++;
        } else {
            compressed.push_back(count);
            compressed.push_back(current);
            current = raw_data[i];
            count = 1;
        }
    }
    compressed.push_back(count);
    compressed.push_back(current);
    raw_data = compressed;
},O(n)

