// Optimized delta-encoded pagination index for large integer list
// Given a page number, find the starting index in O(log n)
size_t findPageStart(const std::vector<uint64_t>& pages, size_t pageNumber) {
    // pages holds cumulative counts of items per page, sorted ascending
    size_t left = 0, right = pages.size() - 1, mid;
    while (left <= right) {
        mid = left + ((right - left) >> 1);
        if (pages[mid] < pageNumber) left = mid + 1;
        else right = mid - 1;
    }
    return left; // first page that starts at or after pageNumber
}
,O(log n)

