void apply_reverb_samples(float* samples, int count, ReverbParams& rev) {
    for (int i = 0; i < count; ++i) {
        float delayed = samples[i] + rev.delay_buffer[(rev.delay_idx + rev.delay_length - rev.delay_time) % rev.delay_length] * rev.feedback;
        rev.delay_buffer[rev.delay_idx] = delayed;
        samples[i] = delayed + rev.wet_mix * rev.delay_buffer[(rev.delay_idx + rev.delay_length - rev.delay_time * 2) % rev.delay_length];
        rev.delay_idx = (rev.delay_idx + 1) % rev.delay_length;
    }
},O(n)

