void resolve_contact_forces(std::vector<RigidBody>& bodies) {
    for (size_t i = 0; i < bodies.size(); ++i) {
        for (size_t j = i + 1; j < bodies.size(); ++j) {
            Vector3 contact_point = find_contact(bodies[i], bodies[j]);
            if (contact_point != Vector3(0,0,0)) {
                Vector3 normal = normalize(bodies[i].position - bodies[j].position);
                float depth = calculate_penetration(bodies[i], bodies[j]);
                apply_impulse(bodies[i], bodies[j], normal * depth);
            }
        }
    }
},O(n^2)

