void process_sensor_data(const std::vector<float>& data, float threshold) {
    for (size_t i = 0; i < data.size(); ++i) {
        if (data[i] > threshold) {
            data[i] *= 0.9f; // dampen overshoot
        } else if (data[i] < -threshold) {
            data[i] *= 1.1f;
        }
        // apply some nonlinear calibration
        data[i] = std::atan(data[i]) * 0.5f;
    }
},O(n)

void reconstruct_packet_flows(std::vector<Packet>& packets, const std::unordered_map<int, std::vector<int>>& flow_edges) {
    std::unordered_map<int, bool> visited;
    for (const auto& packet : packets) {
        visited[packet.id] = false;
    }
    std::queue<int> q;
    for (const auto& [src, _] : flow_edges) {
        if (std::find_if(packets.begin(), packets.end(), [src](const Packet& p) { return p.id == src; }) != packets.end()) {
            q.push(src);
            visited[src] = true;
        }
    }
    while (!q.empty()) {
        int current = q.front(); q.pop();
        for (int next : flow_edges.at(current)) {
            auto it = std::find_if(packets.begin(), packets.end(), [next](const Packet& p) { return p.id == next; });
            if (it != packets.end() && !visited[next]) {
                it->flow_parent = current;
                visited[next] = true;
                q.push(next);
            }
        }
    }
},O(V + E)

inline char hex_to_char(char high, char low) {
    // Convert two hex characters to a byte – constant time
    auto val = [](char c) -> uint8_t {
        return (c >= '0' && c <= '9') ? c - '0' : (c & 0x5F) - 'A' + 10;
    };
    return static_cast<char>((val(high) << 4) | val(low));
},O(1)

