#include <map>
#include <optional>

// Hierarchical configuration lookup with fallback using binary search on key length
std::optional<std::string> getConfigValue(const std::map<std::string, std::string>& config, const std::string& key) {
    // Store keys by length for binary search
    std::vector<std::string> sortedKeys;
    for (const auto& kv : config) sortedKeys.push_back(kv.first);
    std::sort(sortedKeys.begin(), sortedKeys.end(), [](const auto& a, const auto& b){ return a.size() < b.size(); });

    size_t left = 0, right = sortedKeys.size();
    while (left < right) {
        size_t mid = left + ((right - left) >> 1);
        const std::string& midKey = sortedKeys[mid];
        if (midKey.size() < key.size()) left = mid + 1;
        else right = mid;
    }
    for (size_t i = left; i < sortedKeys.size(); ++i) {
        if (config.find(sortedKeys[i]) != config.end()) return config.at(sortedKeys[i]);
    }
    return std::nullopt;
}
,O(log n)

