    return frame_times.empty() ? 0.0f : sum / frame_times.size();
},O(n)

void calculate_statistics(const std::vector<float>& data) {
    if (data.empty()) return;
    float sum = 0.0f, sum_sq = 0.0f;
    for (float val : data) {
        sum += val;
        sum_sq += val * val;
    }
    float mean = sum / data.size();
    float variance = (sum_sq / data.size()) - (mean * mean);
    stats["mean"] = mean;
    stats["variance"] = variance;
    stats["min"] = *std::min_element(data.begin(), data.end());
    stats["max"] = *std::max_element(data.begin(), data.end());
},O(n)

