        }
    }
},O(n^2)

void rebuild_spatial_hash(Entity* entities, int entity_count, SpatialGrid& grid) {
    grid.cell_count = 0;
    memset(grid.cells, 0, sizeof(GridCell) * MAX_GRID_CELLS);
    for (int i = 0; i < entity_count; ++i) {
        if (!entities[i].active) continue;
        int cell_x = static_cast<int>(entities[i].position.x / grid.cell_size);
        int cell_y = static_cast<int>(entities[i].position.y / grid.cell_size);
        int cell_idx = cell_y * grid.dimensions.x + cell_x;
        if (cell_idx >= 0 && cell_idx < MAX_GRID_CELLS) {
            grid.cells[cell_idx].entities[grid.cells[cell_idx].count++] = &entities[i];
            if (grid.cells[cell_idx].count > grid.max_per_cell) grid.max_per_cell = grid.cells[cell_idx].count;
        }
    }
},O(n)

