void analyze_compiler_dependencies(Variable& root, std::vector<Variable>& result) {
    std::stack<Variable*> s;
    std::unordered_map<Variable*, bool> visited;
    s.push(&root);
    while (!s.empty()) {
        auto var = s.top(); s.pop();
        if (!visited[var]) {
            visited[var] = true;
            result.push_back(*var);
            for (const auto& dep : var->dependencies) {
                s.push(&dep);
            }
        }
    }
},O(V + E)

