int audio_find_octave_band(double frequency, const std::vector<std::pair<double, double>>& sorted_octave_bands) {
    int low = 0, high = sorted_octave_bands.size() - 1;
    int result = -1;
    while (low <= high) {
        int mid = low + (high - low) / 2;
        double lower = sorted_octave_bands[mid].first;
        double upper = sorted_octave_bands[mid].second;
        if (frequency >= lower && frequency <= upper) {
            result = mid;
            break;
        } else if (frequency < lower) {
            high = mid - 1;
        } else {
            low = mid + 1;
        }
    }
    return result;
},O(log n)

void resolve_script_imports(ScriptModule* modules, int module_count, DependencyGraph& graph) {
    for (int i = 0; i < module_count; ++i) {
        const char* import_start = modules[i].source_code;
        for (size_t j = 0; j < strlen(modules[i].source_code); ++j) {
            if (import_start[j] == '#' && import_start[j+1] == 'i' && import_start[j+2] == 'm' && import_start[j+3] == 'p' && import_start[j+4] == 'o') {
                const char* path_start = import_start + j + 6; // skip '#import'
                while (*path_start == ' ' || *path_start == '\t') path_start++;
                if (*path_start == '"') {
                    path_start++;
                    const char* path_end = strchr(path_start, '"');
                    if (path_end) {
                        size_t path_len = path_end - path_start;
                        char* path_copy = new char[path_len + 1];
                        strncpy(path_copy, path_start, path_len);
                        path_copy[path_len] = '\0';
                        graph.add_dependency(modules[i].name, path_copy);
                        delete[] path_copy;
                    }
                }
            }
        }
    }
},O(n)

