void parse_csv_with_quoted_fields(const std::string& data, std::vector<std::vector<std::string>>& out) {
    // O(n^2) because we repeatedly scan the line for commas inside quotes
    std::istringstream ss(data);
    std::string line;
    while (std::getline(ss, line)) {
        std::vector<std::string> fields;
        for (size_t i = 0; i < line.size(); ++i) {
            if (line[i] == '"') {
                // find closing quote, scanning whole rest of line each time -> O(m^2) per line
                size_t j = i + 1;
                while (j < line.size() && line[j] != '"') ++j;
                fields.push_back(line.substr(i + 1, j - i - 1));
                i = j;
            } else {
                size_t j = i;
                while (j < line.size() && line[j] != ',') ++j;
                fields.push_back(line.substr(i, j - i));
                i = j;
            }
        }
        out.push_back(std::move(fields));
    }
}
,O(n^2)

