#include <sstream>

// Recursive descent parser for simple arithmetic expressions that evaluates in O(log n)
class ExprParser {
public:
    static int parse(const std::string& expr) {
        std::istringstream ss(expr);
        return parseExpression(ss);
    }
private:
    static int parseExpression(std::istringstream& ss) {
        int value = parseTerm(ss);
        char op;
        while (ss >> op && (op == '+' || op == '-')) {
            int right = parseTerm(ss);
            value = (op == '+') ? value + right : value - right;
        }
        return value;
    }
    static int parseTerm(std::istringstream& ss) {
        int value = parseFactor(ss);
        char op;
        while (ss >> op && (op == '*' || op == '/')) {
            int right = parseFactor(ss);
            value = (op == '*') ? value * right : value / right;
        }
        return value;
    }
    static int parseFactor(std::istringstream& ss) {
        char ch;
        ss >> ch;
        if (isdigit(ch)) {
            ss.unget();
            int val; ss >> val; return val;
        }
        if (ch == '(') {
            int val = parseExpression(ss);
            ss >> ch; // consume ')'
            return val;
        }
        return 0; // error case
    }
};
,O(log n)

void update_particle_states(Particle* particles, int count) {
    for (int i = 0; i < count; ++i) {
        if (particles[i].life <= 0) continue;
        particles[i].velocity.x += particles[i].acceleration.x * g_dt;
        particles[i].velocity.y += particles[i].acceleration.y * g_dt;
        particles[i].position.x += particles[i].velocity.x * g_dt;
        particles[i].position.y += particles[i].velocity.y * g_dt;
        particles[i].life -= g_dt;
        particles[i].rotation += particles[i].angular_vel * g_dt;
        if (particles[i].position.y > water_level_) {
            particles[i].velocity.y *= -0.6f;
            particles[i].position.y = water_level_ - (particles[i].position.y - water_level_);
            particles[i].life *= 0.8f;
        }
    }
},O(n)

