#include <vector>
#include <algorithm>

// Binary indexed tree (Fenwick tree) for dynamic rank queries in O(log n)
class Fenwick {
    std::vector<int> bit;
public:
    Fenwick(int n) : bit(n + 1, 0) {}
    void update(int idx, int delta) {
        for (++idx; idx < (int)bit.size(); idx += idx & -idx) bit[idx] += delta;
    }
    int query(int idx) const {
        int sum = 0;
        for (++idx; idx > 0; idx -= idx & -idx) sum += bit[idx];
        return sum;
    }
    int findByOrder(int k) const { // kth smallest element index
        int idx = 0, mask = 1 << (31 - __builtin_clz(bit.size()));
        while (mask) {
            int t = idx + mask;
            if (t < (int)bit.size() && bit[t] < k) { k -= bit[t]; idx = t; }
            mask >>= 1;
        }
        return idx; // 0-based index
    }
};
,O(log n)

void simulate_packet_routing(NetworkTopology& graph, NodeId source) {
    std::deque<NodeId> q;
    std::unordered_map<NodeId, bool> visited;
    q.push_back(source);
    visited[source] = true;
    while (!q.empty()) {
        auto current = q.front(); q.pop_front();
        for (const auto& [neighbor, link] : graph[current].connections) {
            if (!visited[neighbor]) {
                visited[neighbor] = true;
                link.process_packet();
                q.push_back(neighbor);
            }
        }
    }
},O(V + E)

