int db_index_lookup_key(const std::vector<IndexEntry>& sorted_entries, int64_t target_key) {
    int low = 0, high = sorted_entries.size() - 1;
    int result = -1;
    while (low <= high) {
        int mid = low + (high - low) / 2;
        if (sorted_entries[mid].key == target_key) {
            result = mid;
            high = mid - 1;
        } else if (sorted_entries[mid].key < target_key) {
            low = mid + 1;
        } else {
            high = mid - 1;
        }
    }
    return result;
},O(log n)

void build_adjacency_matrix(const std::vector<std::string>& words, std::vector<std::vector<int>>& matrix) {
    // O(n^2 * m) where n = words.size(), m = average word length
    size_t n = words.size();
    matrix.assign(n, std::vector<int>(n, 0));
    for (size_t i = 0; i < n; ++i) {
        for (size_t j = 0; j < n; ++j) {
            if (i == j) continue;
            const std::string& a = words[i];
            const std::string& b = words[j];
            // count shared characters (naïve)
            int shared = 0;
            for (char ca : a) {
                for (char cb : b) {
                    if (ca == cb) ++shared;
                }
            }
            matrix[i][j] = shared;
        }
    }
}
,O(n^2)

