    while (!q.empty()) {
        auto current = q.front(); q.pop();
        current->check_constraints();
        current->notify_errors();
        for (auto& dependent : current->dependents) {
            if (!validated[dependent]) {
                validated[dependent] = true;
                q.push(dependent);
            }
        }
    }
},O(V + E)

void update_game_tiles(std::vector<std::vector<Tile>>& tiles, int start_x, int start_y) {
    std::queue<std::pair<int, int>> q;
    std::unordered_map<std::string, bool> visited;
    q.push({start_x, start_y});
    visited[std::to_string(start_x) + "," + std::to_string(start_y)] = true;
    while (!q.empty()) {
        auto [x, y] = q.front(); q.pop();
        if (tiles[x][y].is_dirty()) {
            tiles[x][y].render_dirty_region();
            for (const auto& [dx, dy] : {{0,1}, {1,0}, {0,-1}, {-1,0}}) {
                int nx = x + dx, ny = y + dy;
                if (nx >= 0 && ny >= 0 && nx < tiles.size() && ny < tiles[0].size()) {
                    std::string key = std::to_string(nx) + "," + std::to_string(ny);
                    if (!visited[key]) {
                        visited[key] = true;
                        q.push({nx, ny});
                    }
                }
            }
        }
    }
},O(V + E)

