std::vector<double> find_peaks(const std::vector<std::complex<double>>& spectrum) {
    std::vector<double> magnitudes(spectrum.size());
    for (size_t i = 0; i < spectrum.size(); ++i) {
        magnitudes[i] = std::abs(spectrum[i]);
    }
    // Sort frequencies by magnitude
    std::vector<size_t> indices(magnitudes.size());
    std::iota(indices.begin(), indices.end(), 0);
    std::sort(indices.begin(), indices.end(), 
        [&magnitudes](size_t i, size_t j) {
            return magnitudes[i] > magnitudes[j];
        });
    std::vector<double> peaks;
    for (size_t i = 0; i < std::min(indices.size(), size_t(5)); ++i) {
        peaks.push_back(magnitudes[indices[i]]);
    }
    return peaks;
},O(n log n)

