void parse_log_entry(std::string& log) {
    std::unordered_map<std::string, std::string> result;
    size_t pos = 0;
    std::string token;
    while ((pos = log.find(' ', pos)) != std::string::npos) {
        token = log.substr(0, pos);
        if (token.find('=') != std::string::npos) {
            size_t eq_pos = token.find('=');
            result[token.substr(0, eq_pos)] = token.substr(eq_pos+1);
        }
        log.erase(0, pos+1);
        pos = 0;
    }
    if (!log.empty()) {
        if (log.find('=') != std::string::npos) {
            size_t eq_pos = log.find('=');
            result[log.substr(0, eq_pos)] = log.substr(eq_pos+1);
        }
    }
    parsed_logs.push_back(result);
},O(n)

