void build_similarity_index(std::vector<Document>& documents, std::vector<std::pair<size_t, size_t>>& similar_pairs) {
    for (size_t i = 0; i < documents.size(); ++i) {
        for (size_t j = i + 1; j < documents.size(); ++j) {
            int common_words = 0;
            for (const auto& word : documents[i].words) {
                for (const auto& other_word : documents[j].words) {
                    if (word == other_word) { common_words++; break; }
                }
            }
            if (common_words > 0.8 * std::min(documents[i].words.size(), documents[j].words.size())) {
                similar_pairs.emplace_back(i, j);
            }
        }
    }
},O(n^2)

