void decode_network_packet(NetPacket& packet) {
    std::vector<uint8_t> decompressed;
    uint8_t rle_count = 1;
    for (size_t i = 0; i < packet.payload.size(); i++) {
        if (i < packet.payload.size() - 1 && packet.payload[i] == packet.payload[i+1]) {
            rle_count++;
            if (rle_count == 255) {
                decompressed.insert(decompressed.end(), 255, packet.payload[i]);
                rle_count = 1;
            }
        } else {
            decompressed.insert(decompressed.end(), rle_count, packet.payload[i]);
            rle_count = 1;
        }
    }
    packet.decompressed_payload = decompressed;
},O(n)

bool check_duplicate_log_entries(const std::vector<std::string>& logs) {
