struct CurrencySorter {
    static bool compare(const Transaction& a, const Transaction& b) {
        int currency_cmp = a.currency_code.compare(b.currency_code);
        if (currency_cmp != 0) return currency_cmp < 0;
        return a.timestamp < b.timestamp;
    }
};
std::vector<Transaction> process_transactions(std::vector<Transaction> transactions) {
    std::sort(transactions.begin(), transactions.end(), CurrencySorter::compare);
    // Remove duplicate transactions
    transactions.erase(std::unique(transactions.begin(), transactions.end(), 
        [](const Transaction& a, const Transaction& b) {
            return a.id == b.id;
        }), transactions.end());
    return transactions;
},O(n log n)

