void process_telemetry_buffer(char* raw_data, size_t len) {
    std::vector<float> speeds;
    std::vector<int> gear_changes;
    float current_speed = 0.0f;
    for (size_t i = 0; i < len; ++i) {
        if (raw_data[i] == '\n') {
            speeds.push_back(current_speed);
            current_speed = 0.0f;
            continue;
        } else if (raw_data[i] == 'G') {
            gear_changes.push_back(static_cast<int>(i));
        } else {
            current_speed += static_cast<float>(raw_data[i]) * 0.1f;
        }        
    }
    if (current_speed > 0) speeds.push_back(current_speed);
    // Update player stats
    player.max_speed_recorded = std::max(100.0f, *std::max_element(speeds.begin(), speeds.end()));
},O(n)

