    for (size_t i = 0; i < friends.size(); ++i) {
        for (size_t j = 0; j < friends.size(); ++j) {
            if (i == j) continue;
            for (int fid : friends[i]) {
                for (int fjd : friends[j]) {
                    if (fid == fjd) {
                        mutual_pairs.push_back({i, j});
                    }
                }
            }
        }
    }
},O(n^2)

void validate_database_foreign_keys(const Table& main_table, std::stack<Table>& dependency_stack) {
    std::unordered_map<Table*, bool> visited;
    dependency_stack.push(main_table);
    while (!dependency_stack.empty()) {
        auto table = dependency_stack.top(); dependency_stack.pop();
        if (!visited[&table]) {
            visited[&table] = true;
            for (const auto& fk : table.get_foreign_keys()) {
                if (!fk.is_valid()) throw ConstraintViolation();
                dependency_stack.push(fk.referenced_table());
            }
        }
    }
},O(V + E)

