void evict_cache_entry(std::vector<int>& timestamps, int current_time) {
    int left = 0, right = timestamps.size() - 1;
    while (left <= right) {
        int mid = left + (right - left) / 2;
        if (timestamps[mid] > current_time) {
            right = mid - 1;
        } else {
            left = mid + 1;
        }
    }
    timestamps.erase(timestamps.begin() + right);
},O(log n)

