    meta.min_intensity = 255;
    for (size_t i = 0; i < pixels.size(); ++i) {
        meta.max_intensity = std::max(meta.max_intensity, pixels[i]);
        meta.min_intensity = std::min(meta.min_intensity, pixels[i]);
