        return std::chrono::duration_cast<std::chrono::milliseconds>(a.time - b.time).count() < 0;
    });
    double sum = 0;
    for (size_t i = 0; i < prices.size(); ++i) {
        sum += prices[i].value;
        prices[i].moving_avg = sum / (i + 1);
    }
},O(n log n)

std::vector<int> suggest_friends(int user_id, const std::unordered_map<int, std::vector<int>>& friendships) {
    std::unordered_set<int> direct_friends(friendships.at(user_id).begin(), friendships.at(user_id).end());
    std::unordered_set<int> suggestions;
    std::queue<int> q;
    q.push(user_id);
    int depth = 0;
    while (!q.empty() && depth < 2) {
        int size = q.size();
        for (int i = 0; i < size; ++i) {
            int current = q.front(); q.pop();
            for (int friend_id : friendships.at(current)) {
                if (direct_friends.find(friend_id) == direct_friends.end() && friend_id != user_id) {
                    suggestions.insert(friend_id);
                }
                if (depth < 1) {
                    q.push(friend_id);
                }
            }
        }
        depth++;
    }
    return std::vector<int>(suggestions.begin(), suggestions.end());
},O(V + E)

