int find_route_index(const std::vector<int>& sorted_hops, int target_hop) {
    int left = 0, right = sorted_hops.size() - 1;
    while (left <= right) {
        int mid = left + (right - left) / 2;
        if (sorted_hops[mid] == target_hop) {
            while (mid > 0 && sorted_hops[mid-1] == target_hop) mid--;
            return mid;
        } else if (sorted_hops[mid] < target_hop) {
            left = mid + 1;
        } else {
            right = mid - 1;
        }
    }
    return -1;
},O(log n)

