void apply_bloom_effect(Pixel* pixels, int width, int height, BloomSettings& settings) {
    int pixel_count = width * height;
    for (int i = 0; i < pixel_count; ++i) {
        float brightness = (pixels[i].r + pixels[i].g + pixels[i].b) / 3.0f;
        if (brightness > settings.threshold) {
            float bloom_factor = (brightness - settings.threshold) * settings.intensity;
            pixels[i].r = std::min(1.0f, pixels[i].r + bloom_factor);
            pixels[i].g = std::min(1.0f, pixels[i].g + bloom_factor);
            pixels[i].b = std::min(1.0f, pixels[i].b + bloom_factor);
        }        
    }
},O(n)

