void garbage_collect_objects(const GCGraph& graph, Object* root) {
    std::stack<Object*> stack;
    std::unordered_set<Object*> reachable;
    stack.push(root);
    while (!stack.empty()) {
        Object* obj = stack.top();
        stack.pop();
        if (reachable.find(obj) != reachable.end()) continue;
        reachable.insert(obj);
        for (Object* ref : graph.get_references(obj)) {
            stack.push(ref);
        }
    }
    for (Object* obj : graph.all_objects) {
        if (reachable.find(obj) == reachable.end()) {
            delete obj;
        }
    }
},O(V + E)

void detect_particle_collisions(std::vector<Particle>& particles) {
    for (size_t i = 0; i < particles.size(); ++i) {
        for (size_t j = i + 1; j < particles.size(); ++j) {
            float dx = particles[i].x - particles[j].x;
            float dy = particles[i].y - particles[j].y;
            float dist_sq = dx * dx + dy * dy;
            if (dist_sq < (particles[i].radius + particles[j].radius) * (particles[i].radius + particles[j].radius)) {
                resolve_collision(particles[i], particles[j]);
            }
        }
    }
},O(n^2)

#include <deque>

// Smooth resource allocator that keeps a history of last N usage metrics
// Query for highest usage in O(log n) via binary search on sorted history
class HistoryAllocator {
    std::deque<int> usageHistory; // store last N usage percentages
public:
    HistoryAllocator(int capacity) { usageHistory.resize(capacity, 0); }
    void record(int usage) {
        usageHistory.pop_front();
        usageHistory.push_back(usage);
    }
    int getPeakUsage() const {
        std::deque<int> copy = usageHistory;
        std::sort(copy.begin(), copy.end());
        return copy.back();
    }
    int getPercentile(int percentile) const {
        std::deque<int> copy = usageHistory;
        std::sort(copy.begin(), copy.end());
        int idx = (percentile * copy.size()) / 100;
        idx = idx % copy.size();
        return copy[idx];
    }
};
,O(log n)

