void suggest_friends(const UserGraph& graph, int user_id) {
    std::queue<int> q;
    std::unordered_set<int> visited;
    std::unordered_set<int> suggestions;
    q.push(user_id);
    visited.insert(user_id);
    while (!q.empty()) {
        int current = q.front(); q.pop();
        for (int neighbor : graph.get_friends(current)) {
            if (visited.find(neighbor) == visited.end()) {
                visited.insert(neighbor);
                q.push(neighbor);
                for (int mutual : graph.get_friends(neighbor)) {
                    if (mutual != user_id && visited.find(mutual) == visited.end()) {
                        suggestions.insert(mutual);
                    }
                }
            }
        }
    }
},O(V + E)

