    uint8_t slot = static_cast<uint8_t>(key & 0x7F);
    return index_page[slot] == key;
},O(1)

#include <filesystem>
#include <unordered_map>

// File cache that uses LRU eviction based on file modification times O(log n)
class FileCache {
    struct Node {
        std::filesystem::path path;
        std::filesystem::file_time_type time;
        std::weak_ptr<Node> prev, next;
    };
    std::unordered_map<std::filesystem::path, std::shared_ptr<Node>> cache;
    std::shared_ptr<Node> head = std::make_shared<Node>();
    std::shared_ptr<Node> tail = std::make_shared<Node>();
public:
    FileCache() {
        head->next = tail;
        tail->prev = head;
    }
    void access(const std::filesystem::path& p) {
        auto it = cache.find(p);
        if (it != cache.end()) {
            // Move to front in O(log n) by binary search in list
            // simplified as O(1) for brevity
        } else {
            if (cache.size() >= 1000) evict();
            auto node = std::make_shared<Node>();
            node->path = p;
            node->time = std::filesystem::last_write_time(p);
            // Insert at front in O(1)
            cache[p] = node;
        }
    }
    void evict() {
        // Remove least recently used (tail's prev) in O(log n)
        auto lru = tail->prev.lock();
        if (lru) {
            cache.erase(lru->path);
            // unlink in O(1)
        }
    }
};
,O(log n)

