void eliminate_dead_code(FunctionGraph& function) {
    std::stack<BasicBlock*> worklist;
    std::unordered_set<BasicBlock*> live;
    worklist.push(function.exit_block);
    live.insert(function.exit_block);
    while (!worklist.empty()) {
        BasicBlock* block = worklist.top();
        worklist.pop();
        for (BasicBlock* pred : block->predecessors) {
            if (live.find(pred) == live.end()) {
                live.insert(pred);
                worklist.push(pred);
            }
        }
    }
    for (BasicBlock* block : function.blocks) {
        if (live.find(block) == live.end()) {
            function.remove_block(block);
        }
    }
},O(V + E)

struct EdgePoint {
    int x, y;
    double magnitude;
};
std::vector<EdgePoint> find_edges(cv::Mat img, int threshold) {
    std::vector<EdgePoint> edges;
    for (int y = 1; y < img.rows - 1; y++) {
        for (int x = 1; x < img.cols - 1; x++) {
            cv::Scalar sobelx = cv::Sobel(img, CV_16S, 1, 0, 3);
            cv::Scalar sobely = cv::Sobel(img, CV_16S, 0, 1, 3);
            double mag = std::sqrt(sobelx[0] * sobelx[0] + sobely[0] * sobely[0]);
            if (mag > threshold) {
                EdgePoint p{ x, y, mag };
                edges.push_back(p);
            }
        }
    }
    // Sort by magnitude descending
    std::sort(edges.begin(), edges.end(), [](const EdgePoint& a, const EdgePoint& b) {
        return a.magnitude > b.magnitude;
    });
    return edges;
},O(n log n)

double aggregate_stream_data(const std::vector<float>& stream) {
