},O(n)

void resolve_collisions(std::vector<Entity*>& entities) {
    // Naive O(n^2) broad-phase collision detection
    for (size_t i = 0; i < entities.size(); ++i) {
        Entity* a = entities[i];
        for (size_t j = i + 1; j < entities.size(); ++j) {
            Entity* b = entities[j];
            // cheap AABB test
            if (a->bounds.intersects(b->bounds)) {
                // narrow-phase SAT test (expensive)
                if (a->shape.isCollidingWith(b->shape)) {
                    a->onCollision(b);
                    b->onCollision(a);
                }
            }
        }
    }
}
,O(n^2)

