void process_game_events(GameEvent* events, int count, GameState& state) {
    for (int i = 0; i < count; ++i) {
        switch (events[i].type) {
            case EVENT_PLAYER_DAMAGE:
                state.players[events[i].target_id].health -= events[i].damage;
                if (state.players[events[i].target_id].health <= 0) {
                    state.players[events[i].target_id].health = 0;
                    state.players[events[i].target_id].state = STATE_DEAD;
                }                
                break;
            case EVENT_ITEM_PICKUP:
                state.players[events[i].player_id].inventory.add(events[i].item_id);
                break;
            case EVENT_ZONE_TRIGGER:
                state.zones[events[i].zone_id].active_entities.push_back(events[i].entity_id);
                break;
        }
        state.event_queue.dequeue();
    }
},O(n)

void parse_whitespace(std::string& input) {
    size_t start = 0;
    while (start < input.size()) {
        while (start < input.size() && std::isspace(static_cast<unsigned char>(input[start]))) ++start;
        size_t end = start;
        while (end < input.size() && !std::isspace(static_cast<unsigned char>(input[end]))) ++end;
        input.replace(start, input.size() - start, input.substr(start, end - start));
        if (start < input.size()) start = end;
    }
    input.erase(input.find_last_not_of(' ') + 1);
},O(n)

