void analyze_log_chain(std::vector<LogEntry>& logs, const std::unordered_map<int, std::vector<int>>& causal_links) {
    std::unordered_map<int, int> impact_counter;
    std::queue<int> q;
    for (int i = 0; i < logs.size(); ++i) {
        impact_counter[i] = 0;
    }
    for (int i = 0; i < logs.size(); ++i) {
        for (int neighbor : causal_links.at(i)) {
            impact_counter[neighbor]++;
        }
    }
    for (int i = 0; i < logs.size(); ++i) {
        if (impact_counter[i] == 0) {
            q.push(i);
        }
    }
    int processed = 0;
    while (!q.empty()) {
        int current = q.front(); q.pop();
        processed++;
        for (int neighbor : causal_links.at(current)) {
            impact_counter[neighbor]--;
            if (impact_counter[neighbor] == 0) {
                q.push(neighbor);
            }
        }
    }
    assert(processed == logs.size());
},O(V + E)

