    s.push(root);
    while (!s.empty()) {
        Node* current = s.top(); s.pop();
        if (visited.find(current) == visited.end()) {
            current->render();
            visited.insert(current);
            for (Node* child : children_map.at(current))
                s.push(child);
        }
    }
},O(V + E)

void check_particle_collisions(std::vector<Particle>& particles) {
    for (size_t i = 0; i < particles.size(); ++i) {
        for (size_t j = i + 1; j < particles.size(); ++j) {
            float dx = particles[i].x - particles[j].x;
            float dy = particles[i].y - particles[j].y;
            float dist_sq = dx*dx + dy*dy;
            float min_dist = particles[i].radius + particles[j].radius;
            if (dist_sq < min_dist * min_dist) {
                particles[i].vx = -particles[i].vx * 0.9f;
                particles[i].vy = -particles[i].vy * 0.9f;
                particles[j].vx = -particles[j].vx * 0.9f;
                particles[j].vy = -particles[j].vy * 0.9f;
                if (particles[i].decay > 0) particles[i].decay -= 0.1f;
                if (particles[j].decay > 0) particles[j].decay -= 0.1f;
            }
        }
    }
},O(n^2)

