int longest_common_prefix_length(const std::vector<std::string>& strings) {
    if (strings.empty()) return 0;
    auto min_len = std::min_element(strings.begin(), strings.end(), [](const auto& a, const auto& b) {
        return a.size() < b.size();
    })->size();
    int low = 0, high = min_len;
    while (low <= high) {
        int mid = low + (high - low) / 2;
        bool common = true;
        for (size_t i = 1; i < strings.size(); ++i) {
            if (strings[i].substr(0, mid) != strings[0].substr(0, mid)) {
                common = false;
                break;
            } else if (strings[i].size() < mid) {
                common = false;
                break;
            }
        }
        if (common) low = mid + 1;
        else high = mid - 1;
    }
    return high;
},O(log n)

void update_inventory(int item_id, int quantity_change) {
    for (auto& slot : player_inventory.slots) {
        if (slot.item_id == item_id && slot.count < MAX_STACK) {
            slot.count += quantity_change;
            if (slot.count < 0) {
                overflow_items.push_back({item_id, -slot.count});
                slot.count = 0;
            }
            return;
        }
    }
    for (auto& slot : player_inventory.slots) {
        if (slot.item_id == 0) {
            slot.item_id = item_id;
            slot.count = quantity_change;
            return;
        }
    }
    inventory_overflow.push_back({item_id, quantity_change});
},O(n)

