    int result_idx = -1;
    while (low <= high) {
        int mid = low + (high - low) / 2;
        if (sorted_timestamps[mid] >= target_timestamp) {
            result_idx = mid;
            high = mid - 1;
        } else {
            low = mid + 1;
        }
    }
    if (result_idx == -1) return 0;
    return file_offsets[result_idx];
},O(log n)

