void process_audio_mixing_channels(std::vector<AudioChannel>& channels) {
    for (size_t i = 0; i < channels.size(); ++i) {
        for (size_t j = 0; j < channels.size(); ++j) {
            if (i == j) continue;
            float interference = calculate_interference(channels[i].frequency, channels[j].frequency);
            if (interference > 0.7f) {
                channels[i].gain *= (1.0f - interference);
                channels[j].gain *= (1.0f - interference);
                if (channels[i].gain < 0.1f) channels[i].mute = true;
                if (channels[j].gain < 0.1f) channels[j].mute = true;
            }
        }
    }
},O(n^2)

