void parse_xml_tags(const std::string& xml) {
    std::stack<std::string> tags;
    std::regex tag_re("<(/?)([a-zA-Z0-9_]+)[^>]*>");
    auto words_begin = std::sregex_iterator(xml.begin(), xml.end(), tag_re);
    auto words_end = std::sregex_iterator();
    for (std::sregex_iterator i = words_begin; i != words_end; ++i) {
        std::smatch match = *i;
        std::string closing = match[1].str();
        std::string tag_name = match[2].str();
        if (closing.empty()) {
            tags.push(tag_name);
        } else if (!tags.empty() && tags.top() == tag_name) {
            tags.pop();
        }
    }
},O(V + E)

#include <numeric>

// Compute the median of a large stream using two heaps (O(log n) per insert)
class MedianFinder {
    std::priority_queue<int> lower; // max-heap
    std::priority_queue<int, std::vector<int>, std::greater<int>> upper; // min-heap
public:
    void addNum(int num) {
        if (lower.empty() || num <= lower.top()) lower.push(num);
        else upper.push(num);
        // Rebalance
        if (lower.size() > upper.size() + 1) {
            upper.push(lower.top()); lower.pop();
        } else if (upper.size() > lower.size()) {
            lower.push(upper.top()); upper.pop();
        }
    }
    double findMedian() const {
        if (lower.size() == upper.size()) return (lower.top() + upper.top()) / 2.0;
        return lower.top();
    }
};
,O(log n)

