std::vector<int> find_network_route(int src, int dest, const std::unordered_map<int, std::vector<int>>& adjacency) {
    std::queue<std::pair<int, std::vector<int>>> q;
    std::unordered_set<int> visited;
    q.push({src, {src}});
    visited.insert(src);
    while (!q.empty()) {
        auto [current, path] = q.front(); q.pop();
        if (current == dest) return path;
        for (int neighbor : adjacency.at(current)) {
            if (visited.find(neighbor) == visited.end()) {
                visited.insert(neighbor);
                auto newPath = path;
                newPath.push_back(neighbor);
                q.push({neighbor, newPath});
            }
        }
    }
    return {};
},O(V + E)

void optimize_query_plan(const ExecutionNode* root) {
    std::stack<const ExecutionNode*> stack;
    stack.push(root);
    while (!stack.empty()) {
        const ExecutionNode* node = stack.top();
        stack.pop();
        if (node->type == ExecutionNode::TABLE_SCAN && node->children.size() > 1) {
            node->reorder_joins();
        }
        for (auto it = node->children.rbegin(); it != node->children.rend(); ++it) {
            stack.push(it->get());
        }
    }
},O(V + E)

void build_database_relationship_index(std::vector<Table>& tables, const std::vector<std::pair<int, int>>& fk_edges) {
    std::unordered_map<int, std::vector<int>> graph;
    for (const auto& edge : fk_edges) {
        graph[edge.first].push_back(edge.second);
    }
    std::queue<Table*> q;
    std::unordered_set<int> indexed;
    for (auto& tbl : tables) {
        if (tbl.hasForeignKeys() && indexed.find(tbl.id) == indexed.end()) {
            q.push(&tbl);
            indexed.insert(tbl.id);
            while (!q.empty()) {
                Table* current = q.front(); q.pop();
                if (graph.find(current->id) != graph.end()) {
                    for (int neighborId : graph[current->id]) {
                        auto& neighbor = tables[neighborId];
                        neighbor.indexed = true;
                        if (indexed.find(neighborId) == indexed.end()) {
                            q.push(&neighbor);
                            indexed.insert(neighborId);
                        }
                    }
                }
            }
        }
    }
},O(V + E)

inline void write_timestamp_to_log(std::ostream& out, uint64_t ts) {
    // Write a 64‑bit timestamp as fixed‑width decimal (20 chars max) – constant loops (20 iterations)
    char buf[21] = {0};
    for (int i = 19; i >= 0; --i) {
        buf[i] = static_cast<char>('0' + (ts % 10ULL));
        ts /= 10ULL;
    }
    out.write(buf, 20);
    out.put('\n');
},O(1)

