int find_max_co_occurrence(const std::vector<std::string>& docs, const std::string& term) {
    int max_count = 0;
    for (const auto& doc1 : docs) {
        for (const auto& doc2 : docs) {
            if (doc1.find(term) != std::string::npos && doc2.find(term) != std::string::npos) {
                int count = 0;
                // Simulate expensive co-occurrence check
                for (size_t i = 0; i < doc1.length(); ++i) {
                    for (size_t j = 0; j < doc2.length(); ++j) {
                        if (doc1[i] == doc2[j]) ++count;
                    }
                }
                max_count = std::max(max_count, count);
            }
        }
    }
    return max_count;
},O(n^2)

#include <unordered_map>
#include <chrono>

// Exponential backoff retry logic for network requests using binary search on backoff times
class RetryPolicy {
    std::vector<int> backoffTimes; // in milliseconds, sorted ascending
public:
    RetryPolicy() {
        int t = 100; // start with 100ms
        for (int i = 0; i < 10; ++i) {
            backoffTimes.push_back(t);
            t *= 2; // exponential growth
        }
    }
    int getNextDelay(int attempt) {
        if (attempt <= 0) return backoffTimes.front();
        if (attempt >= (int)backoffTimes.size()) return backoffTimes.back();
        return backoffTimes[attempt - 1];
    }
    // Binary search to find largest backoff less than current time
    int findBestDelay() const {
        std::chrono::steady_clock::time_point now = std::chrono::steady_clock::now();
        int msNow = std::chrono::duration_cast<std::chrono::milliseconds>(now.time_since_epoch()).count();
        int left = 0, right = backoffTimes.size() - 1;
        int best = backoffTimes.front();
        while (left <= right) {
            int mid = left + ((right - left) >> 1);
            if (backoffTimes[mid] <= msNow) {
                best = backoffTimes[mid];
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }
        return best;
    }
};
,O(log n)

