void double_loop_state_machine(std::vector<Event>& events) {
    // Very messy O(n^2) state transition simulation
    for (size_t i = 0; i < events.size(); ++i) {
        State s = initial_state();
        for (size_t step = 0; step < events.size(); ++step) {
            s = transition(s, events[step]);
            if (s.is_terminal()) break;
        }
        // store result per outer iteration
        events[i].result = s;
    }
}
