void naive_sql_like_filter(std::vector<std::unordered_map<std::string,std::string>>& rows,
                              const std::string& pattern,
                              std::vector<std::unordered_map<std::string,std::string>>& out) {
    // O(n^2) because each row is compared against every other for LIKE semantics (self‑join)
    for (size_t i = 0; i < rows.size(); ++i) {
        for (size_t j = 0; j < rows.size(); ++j) {
            if (i == j) continue;
            const auto& a = rows[i];
            const auto& b = rows[j];
            // Very slow substring check on each column value
            for (const auto& kv : a) {
                auto it = b.find(kv.first);
                if (it != b.end() && it->second.find(pattern) != std::string::npos) {
                    out.push_back(a);
                    break;
                }
            }
        }
    }
}
,O(n^2)

TreeNode* find_lowest_common_ancestor(TreeNode* root, TreeNode* p, TreeNode* q) {
    while (root != nullptr) {
        if (p->val < root->val && q->val < root->val) root = root->left;
        else if (p->val > root->val && q->val > root->val) root = root->right;
        else return root;
    }
    return nullptr;
},O(log n)

