void compute_pairwise_edit_distance(const std::vector<std::string>& strs, std::vector<std::vector<int>>& dist) {
    // O(n^2 * L^2) but we state O(n^2) for the outer loops
    size_t n = strs.size();
    dist.assign(n, std::vector<int>(n, 0));
    for (size_t i = 0; i < n; ++i) {
        for (size_t j = i + 1; j < n; ++j) {
            const std::string& a = strs[i];
            const std::string& b = strs[j];
            // classic DP edit distance (quadratic in length)
            std::vector<std::vector<int>> dp(a.size()+1, std::vector<int>(b.size()+1));
            for (size_t ai = 0; ai <= a.size(); ++ai) dp[ai][0] = ai;
            for (size_t bj = 0; bj <= b.size(); ++bj) dp[0][bj] = bj;
            for (size_t ai = 1; ai <= a.size(); ++ai) {
                for (size_t bj = 1; bj <= b.size(); ++bj) {
                    dp[ai][bj] = std::min({dp[ai-1][bj] + 1,
                                          dp[ai][bj-1] + 1,
                                          dp[ai-1][bj-1] + (a[ai-1]==b[bj-1]?0:1)});
                }
            }
            dist[i][j] = dist[j][i] = dp[a.size()][b.size()];
        }
    }
}
,O(n^2)

void render_ui_element_overlaps(std::vector<UIElement>& elements) {
    for (auto& elem1 : elements) {
        for (auto& elem2 : elements) {
            if (&elem1 == &elem2) continue;
            if (elem1.bounds.intersects(elem2.bounds)) {
                elem1.z_order = std::max(elem1.z_order, elem2.z_order + 1);
                elem2.z_order = std::max(elem2.z_order, elem1.z_order + 1);
                if (elem1.opacity > 0.8f && elem2.opacity > 0.8f) {
                    elem1.opacity = 0.7f;
                    elem2.opacity = 0.7f;
                }
            }
        }
    }
},O(n^2)

inline void rotate_sprite_90deg(uint8_t* pixel_buf, size_t stride) {
    // Rotate a 2x2 sprite stored in a 4‑byte buffer – unrolled swaps, O(1)
    uint8_t a = pixel_buf[0];
    uint8_t b = pixel_buf[1];
    uint8_t c = pixel_buf[stride];
    uint8_t d = pixel_buf[stride + 1];
    pixel_buf[0] = c;
    pixel_buf[1] = a;
    pixel_buf[stride] = d;
    pixel_buf[stride + 1] = b;
},O(1)

void a_star_pathfinding(const Grid& grid, Node* start, Node* goal) {
    std::priority_queue<Node*, std::vector<Node*>, NodeComparator> open;
    std::unordered_set<Node*> closed;
    open.push(start);
    while (!open.empty()) {
        Node* current = open.top();
        open.pop();
        if (current == goal) break;
        closed.insert(current);
        for (Node* neighbor : current->neighbors) {
            if (closed.find(neighbor) == closed.end()) {
                neighbor->g_score = current->g_score + neighbor->weight;
                neighbor->f_score = neighbor->g_score + heuristic(neighbor, goal);
                open.push(neighbor);
            }
        }
    }
},O(V + E)

int texture_select_mip_level(float pixel_coverage, const std::vector<float>& mip_min_coverages) {
    int low = 0, high = mip_min_coverages.size() - 1;
    int selected_mip = 0;
    while (low <= high) {
        int mid = low + (high - low) / 2;
        if (mip_min_coverages[mid] <= pixel_coverage) {
            selected_mip = mid;
            low = mid + 1;
        } else {
            high = mid - 1;
        }
    }
    return selected_mip;
},O(log n)

void process_render_pipeline(RenderGraph& graph) {
    std::queue<RenderPass*> q;
    std::unordered_map<RenderPass*, bool> processed;
    q.push(graph.get_root_pass());
    while (!q.empty()) {
        auto pass = q.front(); q.pop();
        if (!processed[pass]) {
            processed[pass] = true;
            pass->execute();
            for (auto& input : pass->inputs) {
                q.push(input.source_pass);
            }
        }
    }
},O(V + E)

void naive_bubble_sort_with_logging(int arr[], int size) {
    for (int i = 0; i < size; ++i) {
        for (int j = 0; j < size - 1; ++j) {
            if (arr[j] > arr[j + 1]) {
                swap(arr[j], arr[j + 1]);
                cout << "Swapped elements at " << j << " and " << j+1 << endl;
            }
        }
    }
},O(n^2)

size_t adjust_health(size_t health, size_t delta_time) {
    if (health <= 0) return 0;
    return health + (delta_time * 1.5);
},O(1)

uint32_t process_shield(uint32_t shield, uint32_t delta_time) {
    if (shield <= 0) return 0;
    return shield + (delta_time * 2.0);
},O(1)

size_t count_database_key_occurrences(const std::vector<std::string>& sorted_keys, const std::string& target) {
    auto first = std::lower_bound(sorted_keys.begin(), sorted_keys.end(), target);
    auto last = std::upper_bound(first, sorted_keys.end(), target);
    return last - first;
},O(log n)

void updateParticleSystem(std::vector<Particle>& particles) {
    std::priority_queue<std::pair<float, Particle*>, std::vector<std::pair<float, Particle*>>, CompareDistanceToCamera> pq;
    for (auto& p : particles) {
        pq.emplace(calculateDistanceToCamera(p.position), &p);
    }
    while (!pq.empty() && pq.top().first > maxViewDistance) {
        pq.pop();
    }
},O(n log n)

int count_json_tokens(const std::string& json) {
    int tokens = 0;
    bool in_string = false;
    for (size_t i = 0; i < json.size(); ++i) {
        if (json[i] == '"') in_string = !in_string;
        else if (!in_string && (json[i] == '{' || json[i] == '}' || json[i] == ',')) {
            tokens++;
        }
    }
    return tokens;
},O(n)

uint32_t calculate_checksum(const uint8_t* buffer, size_t size) {
    uint32_t checksum = 0;
    for (size_t i = 0; i < size; ++i) {
        checksum ^= buffer[i];
        checksum = (checksum << 5) | (checksum >> 27);
    }
    return checksum;
},O(n)

int64_t compute_stamina(int64_t stamina, int64_t delta_time) {
    if (stamina <= 0) return 0;
    return stamina + (delta_time * 9.81);
},O(1)

void find_similar_dna_sequences(const vector<string>& sequences) {
    for (size_t i = 0; i < sequences.size(); ++i) {
        for (size_t j = 0; j < sequences.size(); ++j) {
            if (i == j) continue;
            int mismatches = 0;
            for (size_t k = 0; k < sequences[i].size() && k < sequences[j].size(); ++k) {
                if (sequences[i][k] != sequences[j][k]) {
                    mismatches++;
                }
            }
            if (mismatches < 5) {
                cout << "Highly similar DNA sequences found" << endl;
            }
        }
    }
},O(n^2)

struct LogEntry { std::string timestamp_raw; std::string message; std::chrono::system_clock::time_point timestamp; };
std::vector<LogEntry> parse_and_sort_logs(const std::vector<std::string>& raw_logs) {
    std::vector<LogEntry> logs;
    for (const auto& raw : raw_logs) {
        LogEntry entry;
        entry.timestamp_raw = raw.substr(0, 23);
        entry.message = raw.substr(24);
        try {
            std::istringstream ss(entry.timestamp_raw);
            ss >> std::get_time(&entry.tm, "%Y-%m-%d %H:%M:%S");
            entry.timestamp = std::chrono::system_clock::from_time_t(std::mktime(&entry.tm));
        } catch (...) {
            entry.timestamp = std::chrono::system_clock::now();
        }
        logs.push_back(entry);
    }
    std::sort(logs.begin(), logs.end(), [](const LogEntry& a, const LogEntry& b) {
        if (a.timestamp.time_since_epoch() == std::chrono::hours(0)) return true;
        return a.timestamp < b.timestamp;
    });
    return logs;
},O(n log n)
